"""Integration test for the Postgres table names generated by the application."""

import os
from collections.abc import Callable

import psycopg
import pytest
from fastapi.testclient import TestClient

from etlalchemy.app.api.app import create_app

DSN = os.environ.get("TEST_DATABASE_URL") or os.environ.get("ETLALCHEMY_DSN")

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(not DSN, reason="TEST_DATABASE_URL is not set"),
]

TABLES = (
    "catalog_catalogs",
    "catalog_schemas",
    "catalog_tables",
    "catalog_fields",
    "catalog_application_events",
    "catalog_projection_tracking",
    "ingestion_connections",
    "ingestion_import_runs",
    "ingestion_application_events",
    "ingestion_projection_tracking",
    "vocabulary_domains",
    "vocabulary_terms",
    "vocabulary_term_aliases",
    "vocabulary_term_links",
    "vocabulary_application_events",
    "vocabulary_projection_tracking",
    "semantic_models",
    "semantic_entities",
    "semantic_relationships",
    "semantic_relationship_fields",
    "semantic_diagrams",
    "semantic_nodes",
    "semantic_application_events",
    "semantic_projection_tracking",
    "comment_threads",
    "comment_comments",
    "comment_mentions",
    "comment_application_events",
    "comment_projection_tracking",
    "iam_tenants",
    "iam_users",
    "iam_tenant_members",
    "iam_identities",
    "iam_password_creds",
    "iam_oidc_creds",
    "iam_api_keys",
    "iam_sessions",
    "iam_groups",
    "iam_group_members",
    "iam_permission_grants",
    "iam_auth_providers",
    "iam_casbin_rules",
    "iam_audit_log",
    "iam_application_events",
    "iam_projection_tracking",
    "llm_config_providers",
    "llm_config_provider_shares",
    "llm_config_provider_defaults",
    "llm_config_application_events",
    "llm_config_projection_tracking",
    "conversation_conversations",
    "conversation_messages",
    "conversation_message_resources",
    "conversation_message_tools",
    "conversation_runs",
    "conversation_approvals",
    "conversation_application_events",
    "conversation_projection_tracking",
)
OLD_TABLES = (
    "catalogapplication_events",
    "catalogprojection_tracking",
    "ingestionapplication_events",
    "ingestionprojection_tracking",
)


def test_postgres_table_names_are_snake_case(
    config_dir: object,
    write_config: Callable[[str], None],
) -> None:
    """The application derives snake_case event store and tracking table names."""
    write_config(f"database:\n  backend: postgres\n  postgres_dsn: {DSN}\n")

    with psycopg.connect(DSN or "") as connection, connection.cursor() as cursor:
        for table in (*TABLES, *OLD_TABLES):
            cursor.execute(f'DROP TABLE IF EXISTS "{table}" CASCADE')

    app = create_app()
    with TestClient(app):
        pass

    with psycopg.connect(DSN or "") as connection, connection.cursor() as cursor:
        cursor.execute(
            "SELECT table_name FROM information_schema.tables "
            "WHERE table_schema = 'public' AND "
            "(table_name LIKE 'catalog%' OR table_name LIKE 'ingestion%' "
            "OR table_name LIKE 'vocabulary%' OR table_name LIKE 'semantic%' "
            "OR table_name LIKE 'comment%' OR table_name LIKE 'iam%' "
            "OR table_name LIKE 'llm_config%' OR table_name LIKE 'conversation%' "
            "OR table_name IN ('checkpoints', 'checkpoint_writes'))"
        )
        found = {row[0] for row in cursor.fetchall()}

    assert set(TABLES) <= found
    for old_table in OLD_TABLES:
        assert old_table not in found
